"""
    Author: Chaitanya Vella (chaitanya-vella.kumar@broadcom.com)
    Common function to remove the last line of the string
    :param data:
    :return:
    """
def remove_last_line_from_string(data: Any) -> object {
    return data[:data.rfind('\n')];
}

